/// <reference types="../../../types/react-table-config" />

import React, { useState } from 'react';
import { FormattedMessage } from 'react-intl';
import { isElement } from 'react-is';
import type { ColumnInstance, TableDispatch } from 'react-table';

import { ArrowSmallDownIcon, ArrowSmallUpIcon } from '@dynatrace/strato-icons';

import { TableUserActions } from './TableUserActions.js';
import { useActionsMenuAlignment } from './useActionMenuAlignment.js';
import { TableUserActionsContext } from './useTableUserActionsContext.js';
import { Menu } from '../../../../navigation/menu/Menu.js';
import { dataTableMessages } from '../../../DataTable/messages.js';

export type ColumnActionsMenuProps = {
  column: ColumnInstance;
  tableUserActions: React.ReactElement | null;
  trigger: React.ReactNode;
  dispatch: TableDispatch;
  defaultActions: React.ReactElement[];
  customActions: React.ReactElement[];
  headerButtonRef: React.RefObject<HTMLButtonElement>;
  tableContainerRef: React.RefObject<HTMLDivElement>;
};
export const ColumnActionsMenu = ({
  column,
  tableUserActions,
  dispatch,
  trigger,
  defaultActions,
  customActions,
  headerButtonRef,
  tableContainerRef,
}: ColumnActionsMenuProps) => {
  const { canSortViaUserAction, isSorted, isSortedDesc } = column;
  const [menuOpen, setMenuOpen] = useState(false);

  const wrappedUserActions =
    isElement(tableUserActions) && tableUserActions.type !== TableUserActions;

  const alignment = useActionsMenuAlignment(
    tableContainerRef,
    headerButtonRef,
    column,
  );

  return (
    <TableUserActionsContext.Provider value={{ column, dispatch }}>
      <Menu open={menuOpen} onOpenChange={setMenuOpen}>
        <Menu.Trigger>{trigger}</Menu.Trigger>
        {menuOpen && (
          <Menu.Content alignment={alignment}>
            {(canSortViaUserAction || defaultActions.length > 0) && (
              <Menu.Group>
                {canSortViaUserAction && (
                  <>
                    <Menu.Item
                      onSelect={() => {
                        if (isSorted) {
                          if (isSortedDesc) {
                            column.toggleSortBy(false);
                          } else {
                            column.clearSortBy();
                          }
                        } else {
                          column.toggleSortBy(false);
                        }
                      }}
                    >
                      <Menu.ItemIcon>
                        <ArrowSmallUpIcon />
                      </Menu.ItemIcon>
                      <FormattedMessage
                        {...dataTableMessages.sortAscendingLabel}
                      />
                    </Menu.Item>
                    <Menu.Item
                      onSelect={() => {
                        if (isSorted) {
                          if (isSortedDesc) {
                            column.clearSortBy();
                          } else {
                            column.toggleSortBy(true);
                          }
                        } else {
                          column.toggleSortBy(true);
                        }
                      }}
                    >
                      <Menu.ItemIcon>
                        <ArrowSmallDownIcon />
                      </Menu.ItemIcon>
                      <FormattedMessage
                        {...dataTableMessages.sortDescendingLabel}
                      />
                    </Menu.Item>
                  </>
                )}
                {defaultActions}
              </Menu.Group>
            )}
            {wrappedUserActions ? tableUserActions : customActions}
          </Menu.Content>
        )}
      </Menu>
    </TableUserActionsContext.Provider>
  );
};
